import { useRouter, useParams } from "next/navigation";
import { useState, useEffect, useCallback } from "react";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";
import { useMutation, useQuery } from "@tanstack/react-query";
import { toast, ToastContainer } from "react-toastify";
import Select from "react-select";
import { Product, Category, ProductStatus } from "@/types/product";
import axiosInstance from "@/utils/axiosInstance";
import { updateProduct, fetchProduct, fetchCategories } from "@/components/product/api";
import AccessDenied from "@/components/common/AccessDenied";

type InitialValues = {
  productName: string;
  detail: string;
  price: number;
  weight: number;
  productCategory: string;
};

type ProductFormProps = {
  initialValues: InitialValues;
  categories: Category[];
  productId: string;
};

type ImageData = {
  position: number;
  productPictureUrl: string | null;
  pictureId: number | null;
};

const EditDraftProduct = () => {
  const router = useRouter();
  const { productId } = useParams<{ productId: string }>();

  const [initialValues, setInitialValues] = useState<InitialValues>({
    productName: "",
    detail: "",
    price: 0,
    weight: 0,
    productCategory: "",
  });

  const { data: product, isLoading: isProductLoading } = useQuery<Product>({
    queryKey: ["product", productId],
    queryFn: () => fetchProduct(productId),
    enabled: !!productId,
  });

  const { data: categories, isLoading: isCategoriesLoading } = useQuery<Category[]>({
    queryKey: ["categories"],
    queryFn: fetchCategories,
  });

  const [isUnauthorized, setIsUnauthorized] = useState(false);

  useEffect(() => {
    if (product) {
      if (product.status !== ProductStatus.DRAFT) {
        setIsUnauthorized(true);
        setTimeout(() => router.push("/403"), 2000);
        return;
      }

      const matchedCategory = categories?.find((c) => c.categoryName === product.productCategory);

      setInitialValues({
        productName: product.productName || "",
        detail: product.detail || "",
        price: product.price || 0,
        weight: product.weight || 0,
        productCategory: matchedCategory ? String(matchedCategory.categoryId) : "",
      });
    }
  }, [product, categories, router]);

  if (isProductLoading || isCategoriesLoading) return <div>Loading...</div>;
  if (isUnauthorized) return <AccessDenied />;

  return (
    <div className="p-6 bg-white shadow-md rounded-lg">
      <ToastContainer />
      <h2 className="text-3xl text-gray-500 font-semibold mb-4">Edit Product Draft</h2>
      {initialValues.productName ? (
        <ProductForm initialValues={initialValues} categories={categories || []} productId={productId} />
      ) : (
        <div>Loading product details...</div>
      )}
    </div>
  );
};

const ProductForm = ({ initialValues, categories, productId }: ProductFormProps) => {
  const mutation = useMutation({
    mutationFn: (values: Partial<Product>) => updateProduct({ productId, values }),
    onSuccess: () => toast.success("Product updated successfully!"),
    onError: (error) => toast.error("Failed to update product."),
  });

  return (
    <Formik
      initialValues={initialValues}
      validationSchema={Yup.object({
        productName: Yup.string().min(3).required(),
        detail: Yup.string().min(3).required(),
        price: Yup.number().positive().required(),
        weight: Yup.number().positive().required(),
        productCategory: Yup.string().required(),
      })}
      onSubmit={(values) => {
        mutation.mutate(values);
      }}
    >
      <Form>
        <Field type="text" name="productName" />
        <ErrorMessage name="productName" />
        <Field type="text" name="detail" />
        <ErrorMessage name="detail" />
        <Field type="number" name="price" />
        <ErrorMessage name="price" />
        <Field type="number" name="weight" />
        <ErrorMessage name="weight" />
        <Select
          options={categories.map(({ categoryId, categoryName }) => ({
            value: categoryId,
            label: categoryName,
          }))}
          onChange={(option) => option && option.value}
        />
        <ErrorMessage name="productCategory" />
        <button type="submit">Update Product</button>
      </Form>
    </Formik>
  );
};

export default EditDraftProduct